        for r in rows: t.insert("", "end", iid=r[2], values=(r[0], fmt_time(r[1]), r[3], r[4], r[5], fmt(r[6]) if r[6] else "", fmt(r[7]) if r[7] else "", fmt(r[10]) if r[10] else "", fmt(r[8]) if r[8] else "", fmt(r[9]) if r[9] else ""))
