def tg_approvers(cfg):
    """اللي يوافقوا على الطلبات: المديرين + المحاسبين."""
    out = dict(cfg.get("tg_chats") or {})
    for cid, r in (cfg.get("tg_reps") or {}).items():
        if is_acct(r): out[cid] = r.get("name", "") + " (محاسب)"
    return out

